&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types d&#39;alchimiste&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_dalchimiste_0&quot; href=&quot;#Les_arch&#233;types_dalchimiste_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste-Des-Marais-(Alchimiste).html&quot; title=&quot;Alchimiste des marais&quot;&gt;Alchimiste des marais&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Grippli-(Race).html&quot; title=&quot;Les gripplis&quot;&gt;Grippli&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste-Interne-(Alchimiste).html&quot; title=&quot;Alchimiste interne&quot;&gt;Alchimiste interne&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animorphe-(Alchimiste).html&quot; title=&quot;Animorphe&quot;&gt;Animorphe&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artificier-Des-Profondeurs-(Alchimiste).html&quot; title=&quot;Artificier des profondeurs&quot;&gt;Artificier des profondeurs&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Svirfneblin-(Race).html&quot; title=&quot;Les svirfneblins&quot;&gt;Svirfneblin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brasseur-D&#233;pines-(Alchimiste).html&quot; title=&quot;Brasseur d&amp;#39;&#233;pines&quot;&gt;Brasseur d&#39;&#233;pines&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chercheur-Dœnopion-(Alchimiste).html&quot; title=&quot;Chercheur visionnaire&quot;&gt;Chercheur visionnaire&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Enrag&#233;-(Alchimiste).html&quot; title=&quot;Chimiste enrag&#233;&quot;&gt;Chimiste enrag&#233;&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Inspir&#233;-(Alchimiste).html&quot; title=&quot;Chimiste inspir&#233;&quot;&gt;Chimiste inspir&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Spirituel-(Alchimiste).html&quot; title=&quot;Chimiste spirituel&quot;&gt;Chimiste spirituel&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chirurgien-(Alchimiste).html&quot; title=&quot;Chirurgien&quot;&gt;Chirurgien&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collectionneur-(Alchimiste).html&quot; title=&quot;Collectionneur&quot;&gt;Collectionneur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ectochimiste-(Alchimiste).html&quot; title=&quot;Ectochimiste&quot;&gt;Ectochimiste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Explorateur-De-Cryptes-(Alchimiste).html&quot; title=&quot;Explorateur de cryptes&quot;&gt;Explorateur de cryptes&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grenadier-(Alchimiste).html&quot; title=&quot;Grenadier&quot;&gt;Grenadier&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Hobgobelin-(Race).html&quot; title=&quot;Les hobgobelins&quot;&gt;Hobgobelin&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homonculiste-(Alchimiste).html&quot; title=&quot;Homonculiste &quot;&gt;Homonculiste&lt;/a&gt; (FF)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Interrogateur-(Alchimiste).html&quot; title=&quot;Interrogateur&quot;&gt;Interrogateur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inventeur-Alchimiste-(Alchimiste).html&quot; title=&quot;Inventeur alchimiste&quot;&gt;Inventeur alchimiste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Clones-(Alchimiste).html&quot; title=&quot;Ma&#238;tre des clones&quot;&gt;Ma&#238;tre des clones&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Maraudeur-Ail&#233;-(Alchimiste).html&quot; title=&quot;Maraudeur ail&#233;&quot;&gt;Maraudeur ail&#233;&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-(Alchimiste).html&quot; title=&quot;M&#233;tamorphe&quot;&gt;M&#233;tamorphe&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Porte-Peste-(Alchimiste).html&quot; title=&quot;Porte-peste&quot;&gt;Porte-peste&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;Homme-rat&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Psychonaute-(Alchimiste).html&quot; title=&quot;Psychonaute&quot;&gt;Psychonaute&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pyrobombardier-(Alchimiste).html&quot; title=&quot;Pyrobombardier&quot;&gt;Pyrobombardier&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;animateur-(Alchimiste).html&quot; title=&quot;R&#233;animateur&quot;&gt;R&#233;animateur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saboteur-(Alchimiste).html&quot; title=&quot;Saboteur&quot;&gt;Saboteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;Gnome&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sapeur-Alchimique-(Alchimiste).html&quot; title=&quot;Sapeur alchimique&quot;&gt;Sapeur alchimique&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trappeur-Alchimique-(Alchimiste).html&quot; title=&quot;Trappeur alchimique&quot;&gt;Trappeur alchimique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Kobold-(Race).html&quot; title=&quot;Les kobolds&quot;&gt;Kobold&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vivisectioniste-(Alchimiste).html&quot; title=&quot;Vivisectioniste&quot;&gt;Vivisectioniste&lt;/a&gt; (AM)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de lintrigue (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Intrigue/Art de l&#39;intrigue&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Un interrogateur extrait des informations vitales &#224; partir d&#39;individus r&#233;ticents en utilisant des m&#233;thodes traditionnelles et alchimiques.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Comp&#233;tences de classe&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_de_classe_0&quot; href=&quot;#Comp&#233;tences_de_classe_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un interrogateur ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; &#224; sa liste de comp&#233;tences de classe. Cela modifie les comp&#233;tences de classe de l&#39;alchimiste.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Injections (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Injections_Sur_1&quot; href=&quot;#Injections_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, un interrogateur utilise son talent avec l&#39;alchimie pour cr&#233;er des injections. Chaque jour, un interrogateur peut cr&#233;er un nombre d&#39;injections &#233;gal &#224; son niveau d&#39;alchimiste + son modificateur d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;. Il faut 1 heure pour pr&#233;parer les injections. Une injection est inerte jusqu&#39;&#224; ce que l&#39;interrogateur tente de l&#39;utiliser.&lt;br /&gt;&lt;br /&gt;Utiliser une injection est une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; qui n&#233;cessite une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquesdecontact.html&quot; title=&quot;contact&quot;&gt;attaque de contact&lt;/a&gt; au corps &#224; corps. Si l&#39;attaque touche, la cible d&#39;une injection subit un malus de -2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pendant un nombre de minutes &#233;gal &#224; la moiti&#233; du niveau de classe de l&#39;interrogateur (minimum 1). Si l&#39;interrogateur utilise un s&#233;rum avec cette injection, le malus aux jets de Volont&#233; s&#39;applique &#224; tout jet de sauvegarde effectu&#233; contre le s&#233;rum.&lt;br /&gt;&lt;br /&gt;Si l&#39;attaque &#233;choue, l&#39;injection n&#39;est pas administr&#233;e mais peut &#234;tre utilis&#233;e &#224; nouveau - une fois activ&#233;e, elle conserve sa puissance pendant 1 jour. Une injection qui n&#39;a pas &#233;t&#233; administr&#233;e devient inerte si elle quitte l&#39;interrogateur, et se r&#233;active d&#232;s qu&#39;il la r&#233;cup&#232;re. Les malus de plusieurs injections ne se cumulent pas entre eux, ni avec ceux du &lt;a class=&quot;pagelink&quot; href=&quot;Hypnotiseur.html#REGARDHYPNOTIQUE&quot; title=&quot;L&amp;#39;hypnotiseur&quot;&gt;regard hypnotique&lt;/a&gt; d&#39;un hypnotiseur ou du mal&#233;fice &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Mauvaisœil&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;mauvais œil&lt;/a&gt; d&#39;une sorci&#232;re. Les injections sont des &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;effets mentaux&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;poison&lt;/a&gt;. Cette capacit&#233; remplace les &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#BOMBES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;bombes&lt;/a&gt; de l&#39;alchimiste.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;S&#233;rums (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;S&#233;rums_Sur_2&quot; href=&quot;#S&#233;rums_Sur_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, un interrogateur augmente son pouvoir d&#39;influence sur les autres gr&#226;ce &#224; des s&#233;rums compl&#233;mentaires. Un interrogateur pr&#233;pare ses s&#233;rums en m&#234;me temps que ses injections et peut les appliquer &#224; n&#39;importe quelle injection par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; avant d&#39;effectuer le &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d&#39;attaque&lt;/a&gt; de l&#39;injection. Un interrogateur conna&#238;t un s&#233;rum au niveau 1 et peut choisir un autre s&#233;rum &#224; la place d&#39;une &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#DECOUVERTES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;d&#233;couverte&lt;/a&gt;. Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; des s&#233;rums est &#233;gal &#224; 10 + la moiti&#233; du niveau d&#39;alchimiste de l&#39;interrogateur + son modificateur d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;. Une cr&#233;ature ne peut &#234;tre sous l&#39;effet que d&#39;un seul s&#233;rum &#224; la fois - &#224; l&#39;exception du s&#233;rum de modification de m&#233;moire - et n&#39;importe quel nouveau s&#233;rum administr&#233; &#224; une cr&#233;ature remplace le pr&#233;c&#233;dent. Sauf pr&#233;cision contraire, une cr&#233;ature qui r&#233;ussit son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; contre un s&#233;rum est immunis&#233;e aux effets de ce s&#233;rum pendant 24 heures. Un interrogateur ne peut jamais obtenir une quelconque sorte de mutag&#232;ne ou de cognatog&#232;ne, m&#234;me gr&#226;ce &#224; une d&#233;couverte ou une autre classe. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#MUTAGENES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;mutag&#232;nes&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#MUTAGENEPERSISTANT&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;mutag&#232;ne persistant&lt;/a&gt;.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Charme.&lt;/i&gt;&lt;/b&gt; La cr&#233;ature piqu&#233;e doit r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; ou traiter l&#39;interrogateur de fa&#231;on favorable, comme si elle &#233;tait affect&#233;e par un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-Personne.html&quot; title=&quot;Charme-personne&quot;&gt;charme-personne&lt;/a&gt;&lt;/i&gt; avec un &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; &#233;gal au niveau d&#39;alchimiste de l&#39;interrogateur. Au niveau 8, ce s&#233;rum fonctionne comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-Monstre.html&quot; title=&quot;Charme-monstre&quot;&gt;charme-monstre&lt;/a&gt;&lt;/i&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Coop&#233;ration.&lt;/i&gt;&lt;/b&gt; Si elle rate son jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;, la cible de cette injection est affect&#233;e par un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Suggestion.html&quot; title=&quot;Suggestion&quot;&gt;suggestion&lt;/a&gt;&lt;/i&gt; avec un &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; &#233;gal au niveau d&#39;alchimiste de l&#39;interrogateur. Un alchimiste doit avoir atteint le niveau 8 avant de choisir ce s&#233;rum.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Confusion.&lt;/i&gt;&lt;/b&gt; Si elle rate son jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;, la cr&#233;ature piqu&#233;e est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Confus.html&quot; title=&quot;Confus&quot;&gt;confuse&lt;/a&gt; pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; par niveau d&#39;alchimiste de l&#39;interrogateur. Un alchimiste doit avoir atteint le niveau 6 avant de choisir ce s&#233;rum.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Hypnose.&lt;/i&gt;&lt;/b&gt; La cr&#233;ature piqu&#233;e doit r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; ou devenir &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fascin&#233;.html&quot; title=&quot;Fascin&#233;&quot;&gt;fascin&#233;e&lt;/a&gt; pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; par niveau d&#39;alchimiste de l&#39;interrogateur.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Modification de m&#233;moire.&lt;/i&gt;&lt;/b&gt; Si elle rate son jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;, la cible de cette injection est affect&#233;e par un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Modification-De-M&#233;moire.html&quot; title=&quot;Modification de m&#233;moire&quot;&gt;modification de m&#233;moire&lt;/a&gt;&lt;/i&gt; avec un &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; &#233;gal au niveau d&#39;alchimiste de l&#39;interrogateur. Un alchimiste doit avoir atteint le niveau 12 avant de choisir ce s&#233;rum.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Paralytique.&lt;/i&gt;&lt;/b&gt; Si elle rate son jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;, la cr&#233;ature piqu&#233;e est affect&#233;e par un sort d&#39; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Immobilisation-De-Personne.html&quot; title=&quot;Immobilisation de personne&quot;&gt;immobilisation de personne&lt;/a&gt;&lt;/i&gt; avec un &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; &#233;gal au niveau d&#39;alchimiste de l&#39;interrogateur. Un alchimiste doit avoir atteint le niveau 8 avant de choisir ce s&#233;rum.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;V&#233;rit&#233;.&lt;/i&gt;&lt;/b&gt; Une cr&#233;ature piqu&#233;e avec un s&#233;rum de v&#233;rit&#233; doit r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; ou &#234;tre forc&#233;e de r&#233;pondre honn&#234;tement aux questions de l&#39;interrogateur. L&#39;interrogateur peut poser une question tous les 2 niveaux d&#39;alchimiste (minimum 1). Les r&#233;ponses peuvent &#234;tre br&#232;ves, cryptiques ou r&#233;p&#233;titives, surtout si la cr&#233;ature piqu&#233;e est inamicale, mais elles ne sont jamais fausses. Si une cr&#233;ature a &#233;t&#233; sujette &#224; un s&#233;rum de v&#233;rit&#233; dans la semaine pr&#233;c&#233;dente, tout nouveau s&#233;rum reste sans effet, que la cr&#233;ature r&#233;ussisse son jet de sauvegarde ou non.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;
